#include <iostream>

int main() {
    int price = 4200;
    int& r = price;   // declaration: r is a reference (another name)
    r += 100;         // r is used just like the object itself
    int* p = &price;  // declaration: p is a pointer; here & is address-of
    *p += 100;        // expression: * is dereference, writing through p
    std::cout << price << '\n';   // 4400 - both aliases touched the same int
    return 0;
}

#include <iostream>

void add(int* x, int y) {
    *x += y;              // write through the pointer
}

int main() {
    int v = 5;
    add(&v, 7);           // pass the address of v
    add(&v, 3);
    std::cout << v << '\n';   // 15 - add mutated the caller's v
    return 0;
}

