Trace this program line by line and write its exact output:

```cpp
#include <iostream>

int main() {
    int a = 10;
    int& r = a;
    int* p = &a;
    r = 20;
    *p = 30;
    std::cout << a << '\n';
    return 0;
}
```

Then classify, for each line that uses & or *, whether it is a *declaration* or an *operator*.

independentExercise.solution:
Final position: **120** (and the null call is a no-op).
```cpp
#include <iostream>

void applyFill(int* position, int qty) {
    if (position) *position += qty;   // null guard: optional target
}

void applyFillRef(int& position, int qty) {
    position += qty;                  // target always exists
}

int main() {
    int pos = 0;
    applyFillRef(pos, 100);
    std::cout << pos << '\n';         // 100
    applyFillRef(pos, -30);
    std::cout << pos << '\n';         // 70
    applyFill(&pos, 50);
    std::cout << pos << '\n';         // 120
    applyFill(nullptr, 25);
    std::cout << pos << '\n';         // 120 - guard did nothing
    return 0;
}
```
Pointer style fits an *optional* target (the caller may legitimately have no position to update); reference style documents 'this output always exists' and needs no check at the call site.

